module powers_game(\n    input clk,\n    input rst_n,\n    input start,\n    input [9:0] n,\n    output reg winner,\n    output reg done\n);\n\n    // State definitions with explicit widths\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] INIT    = 3'd1;\n    localparam [2:0] LOOP    = 3'd2;\n    localparam [2:0] CALC_L  = 3'd3;\n    localparam [2:0] UPDATE  = 3'd4;\n    localparam [2:0] FINAL   = 3'd5;\n\n    reg [2:0] state;\n    reg [9:0] i;\n    reg [9:0] s;\n    reg [3:0] ans;\n    reg [3:0] L;\n    reg [31:0] current_power;\n    reg [3:0] exponent;\n    reg [9:0] sqrt_n;\n    reg [3:0] arr [0:15];\n    reg [31:3] is_perfect;  // Using 3 to 31 indices\n\n    // Helper function for square root\n    function [9:0] sqrt;\n        input [9:0] x;\n        reg [9:0] guess;\n        integer i;\n        begin\n            guess = 0;\n            for (i = 15; i >= 0; i = i - 1) begin\n                if ((guess + (10'd1 << i)) * (guess + (10'd1 << i)) <= x) begin\n                    guess = guess + (10'd1 << i);\n                end\n            end\n            sqrt = guess;\n        end\n    endfunction\n\n    integer idx;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            winner <= 1'b0;\n            i <= 10'd0;\n            s <= 10'd0;\n            ans <= 4'd0;\n            L <= 4'd0;\n            current_power <= 32'd1;\n            exponent <= 4'd0;\n            sqrt_n <= 10'd0;\n            // Initialize arr\n            for (idx = 0; idx < 16; idx = idx + 1) arr[idx] <= 4'd0;\n            // Initialize is_perfect\n            for (idx = 3; idx < 32; idx = idx + 1) is_perfect[idx] <= 1'b0;\n        end else begin\n            // Fill arr (only happens once)\n            if (arr[0] == 4'd0 && state == IDLE) begin\n                arr[0] <= 4'd0;\n                arr[1] <= 4'd1;\n                arr[2] <= 4'd2;\n                arr[3] <= 4'd1;\n                arr[4] <= 4'd4;\n                arr[5] <= 4'd3;\n                arr[6] <= 4'd2;\n                arr[7] <= 4'd1;\n                arr[8] <= 4'd5;\n                arr[9] <= 4'd6;\n                arr[10] <= 4'd2;\n                arr[11] <= 4'd1;\n                arr[12] <= 4'd8;\n                arr[13] <= 4'd7;\n                arr[14] <= 4'd5;\n                arr[15] <= 4'd9;\n                // Set perfect powers\n                is_perfect[4] <= 1'b1;\n                is_perfect[8] <= 1'b1;\n                is_perfect[9] <= 1'b1;\n                is_perfect[16] <= 1'b1;\n                is_perfect[25] <= 1'b1;\n                is_perfect[27] <= 1'b1;\n                is_perfect[32] <= 1'b1;\n                is_perfect[36] <= 1'b1;\n                is_perfect[49] <= 1'b1;\n                is_perfect[64] <= 1'b1;\n                is_perfect[81] <= 1'b1;\n                is_perfect[100] <= 1'b1;\n            end\n\n            // State machine\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= INIT;\n                end\n\n                INIT: begin\n                    if (n < 10'd2) begin\n                        ans <= arr[0];\n                        s <= 10'd0;\n                    end else begin\n                        if (n[9]) ans <= arr[9];\n                        else if (n[8]) ans <= arr[8];\n                        else if (n[7]) ans <= arr[7];\n                        else if (n[6]) ans <= arr[6];\n                        else if (n[5]) ans <= arr[5];\n                        else if (n[4]) ans <= arr[4];\n                        else if (n[3]) ans <= arr[3];\n                        else if (n[2]) ans <= arr[2];\n                        else if (n[1]) ans <= arr[1];\n                        else ans <= arr[0];\n                        s <= (n[9] ? 10'd9 : (\n                             n[8] ? 10'd8 : (\n                             n[7] ? 10'd7 : (\n                             n[6] ? 10'd6 : (\n                             n[5] ? 10'd5 : (\n                             n[4] ? 10'd4 : (\n                             n[3] ? 10'd3 : (\n                             n[2] ? 10'd2 : (\n                             n[1] ? 10'd1 : 10'd0)))))))));\n                    end\n                    i <= 10'd3;\n                    sqrt_n <= sqrt(n);\n                    state <= LOOP;\n                end\n\n                LOOP: begin\n                    if (i > sqrt_n) state <= FINAL;\n                    else if (i <= 10'd31 && is_perfect[i]) i <= i + 10'd1;\n                    else begin\n                        current_power <= 32'd1;\n                        exponent <= 4'd0;\n                        L <= 4'd0;\n                        state <= CALC_L;\n                    end\n                end\n\n                CALC_L: begin\n                    if (exponent == 4'd0) current_power <= i;\n                    else current_power <= current_power * i;\n\n                    if (exponent >= 4'd1 && current_power > n) begin\n                        L <= exponent - 4'd1;\n                        state <= UPDATE;\n                    end\n                    else if (current_power <= n) begin\n                        exponent <= exponent + 4'd1;\n                        if (exponent >= 4'd10) begin\n                            L <= exponent;\n                            state <= UPDATE;\n                        end\n                    end\n                    else state <= UPDATE;\n                end\n\n                UPDATE: begin\n                    if (L >= 4'd1 && L <= 4'd15) begin\n                        ans <= ans ^ arr[L];\n                        s <= s + L;\n                    end\n                    i <= i + 10'd1;\n                    state <= LOOP;\n                end\n\n                FINAL: begin\n                    ans <= ans ^ ((n - s) & 10'd1);\n                    winner <= (ans != 4'd0);\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule